"""Mock certpin-vendor-sdk for testing."""
import hashlib

_PINNED_HOSTS = {
    "feed.certpin.dev",
}

def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of certificate."""
    return hashlib.sha256(cert_der).hexdigest()

class PinStore:
    @classmethod
    def load(cls):
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        return host in _PINNED_HOSTS
EOF

